import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";import{C as i}from"./chunks/assets.DjpLsfX1.js";var a=JSON.parse(`{"title":"Site Settings Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/07-setting.md","filePath":"02-consumer/07-setting.md"}`),o={name:`02-consumer/07-setting.md`};function s(n,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[e(`<h1 id="site-settings-management-guide" tabindex="-1">Site Settings Management Guide <a class="header-anchor" href="#site-settings-management-guide" aria-label="Permalink to “Site Settings Management Guide”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>The settings management page is used to view, edit, and add settings for different parts of the site. From this page, you can manage existing settings by group, create new settings, save changes, and clear the site&#39;s settings and Blade caches.</p><h2 id="getting-to-know-the-page" tabindex="-1">Getting to Know the Page <a class="header-anchor" href="#getting-to-know-the-page" aria-label="Permalink to “Getting to Know the Page”">​</a></h2><p><img src="`+i+`" alt="setting-page.webp" width="1907" height="952"></p><h3 id="_1-selecting-a-settings-section" tabindex="-1">1. Selecting a Settings Section <a class="header-anchor" href="#_1-selecting-a-settings-section" aria-label="Permalink to “1. Selecting a Settings Section”">​</a></h3><p>The <strong>Sections</strong> area displays the different settings sections. To view and edit a section&#39;s settings, simply select the section you want.</p><p>The default sections are:</p><ul><li><strong>General:</strong> General site settings</li><li><strong>Media:</strong> Settings related to media</li><li><strong>SEO:</strong> SEO settings</li><li><strong>SMS:</strong> Settings related to text messages</li><li><strong>Theme:</strong> Theme and component settings</li></ul><p>When you select a section, its settings appear in the editing area.</p><h3 id="_2-viewing-and-editing-settings" tabindex="-1">2. Viewing and Editing Settings <a class="header-anchor" href="#_2-viewing-and-editing-settings" aria-label="Permalink to “2. Viewing and Editing Settings”">​</a></h3><p>After you select a section, its settings appear in the main area of the page. Each setting has an appropriate input for viewing or editing its value, based on its defined type.</p><p>To edit a setting:</p><ol><li>Select the section you want from <strong>Sections</strong>.</li><li>Find the setting in the main area of the page.</li><li>Change its value.</li><li>When you have finished making changes, use the settings save button to apply them.</li></ol><p>For example, in the <strong>SEO</strong> section, you can view and edit settings such as keywords, descriptions, the Google Webmaster code, and other related options.</p><h3 id="_3-adding-new-settings" tabindex="-1">3. Adding New Settings <a class="header-anchor" href="#_3-adding-new-settings" aria-label="Permalink to “3. Adding New Settings”">​</a></h3><p>The <strong>Add new setting</strong> area is used to define a new setting in the admin panel.</p><p>To add a new setting, enter the following information:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>Section</code></td><td>The section where the new setting should be placed.</td></tr><tr><td><code>Type</code></td><td>The setting type and the input used to receive its value.</td></tr><tr><td><code>Title</code></td><td>The title displayed for the setting in the admin panel.</td></tr><tr><td><code>Key</code></td><td>The setting&#39;s unique key, used to identify and access it in the system.</td></tr><tr><td><code>Size</code></td><td>The size allocated to the setting in the page layout, from 1 to 12.</td></tr></tbody></table><p>After completing the fields, click <strong>Add to setting</strong> to add the setting to the settings list.</p><p><strong>Note:</strong> The <code>Key</code> value must be unique. You cannot assign the same key to two settings, even if they belong to different sections.</p><p>Treat adding a setting to the list as separate from saving the changes permanently. To apply the changes, use the settings save button.</p><h3 id="_4-saving-settings-for-all-sections" tabindex="-1">4. Saving Settings for All Sections <a class="header-anchor" href="#_4-saving-settings-for-all-sections" aria-label="Permalink to “4. Saving Settings for All Sections”">​</a></h3><p>The settings save button, shown with a save icon at the bottom of the page, is used to apply setting changes.</p><p>This button saves changes to settings across different sections all at once, so there is no need to save each section separately.</p><p>Recommended workflow:</p><ol><li>Edit the settings in the sections you need.</li><li>Add new settings if necessary.</li><li>When you have finished making changes, click the save button.</li></ol><p>To avoid losing changes, make sure they have been saved before leaving the page or finishing your work.</p><h3 id="_5-clearing-the-site-s-settings-and-blade-caches" tabindex="-1">5. Clearing the Site&#39;s Settings and Blade Caches <a class="header-anchor" href="#_5-clearing-the-site-s-settings-and-blade-caches" aria-label="Permalink to “5. Clearing the Site&#39;s Settings and Blade Caches”">​</a></h3><p>The <strong>Clear caches</strong> button in the Tips area is used to clear the settings cache and the site&#39;s Blade cache.</p><p>To use this feature:</p><ol><li>If you have made changes, save them first.</li><li>Click <strong>Clear caches</strong>.</li></ol><p>This operation clears the caches related to settings and the site&#39;s Blade.</p><h2 id="recommended-workflow-for-managing-settings" tabindex="-1">Recommended Workflow for Managing Settings <a class="header-anchor" href="#recommended-workflow-for-managing-settings" aria-label="Permalink to “Recommended Workflow for Managing Settings”">​</a></h2><p>Follow these steps to manage the site&#39;s settings:</p><ol><li>Select the section you want from <strong>Sections</strong>.</li><li>Edit existing settings or create a new setting in <strong>Add new setting</strong>.</li><li>When you have finished making changes, save the settings using the save button.</li><li>If necessary, clear the site&#39;s settings and Blade caches using <strong>Clear caches</strong>.</li></ol>`,36)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};